<?php
require_once dirname(__DIR__).'/includes/functions.php';$token=$_GET['token']??$_POST['token']??'';$stmt=$con->prepare("SELECT * FROM password_resets WHERE token=? AND used=0 AND expires_at>NOW() LIMIT 1");$stmt->bind_param('s',$token);$stmt->execute();$reset=$stmt->get_result()->fetch_assoc();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$reset){$pw=$_POST['password']??'';if(strlen($pw)<8)$error='Use at least 8 characters.';elseif($pw!==($_POST['confirm']??''))$error='Passwords do not match.';else{$hash=password_hash($pw,PASSWORD_DEFAULT);$stmt=$con->prepare('UPDATE users SET password=? WHERE id=?');$stmt->bind_param('si',$hash,$reset['user_id']);$stmt->execute();$con->query('UPDATE password_resets SET used=1 WHERE id='.(int)$reset['id']);flash('success','Password updated. Sign in with your new password.');header('Location:'.url('auth/login.php'));exit;}}
$pageTitle='Choose new password';require dirname(__DIR__).'/includes/header.php';?><div class="container py-5"><div class="card p-4 mx-auto" style="max-width:480px"><h1 class="h3">Choose a new password</h1><?php if(!$reset):?><div class="alert alert-danger">This reset link is invalid or expired.</div><?php else:?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="token" value="<?=e($token)?>"><input type="password" name="password" class="form-control mb-3" placeholder="New password" required minlength="8"><input type="password" name="confirm" class="form-control mb-3" placeholder="Confirm password" required><button class="btn btn-primary w-100">Update password</button></form><?php endif?></div></div><?php require dirname(__DIR__).'/includes/footer.php';?>
